function isFirstInContext(
  printStack: Array<t.Node>,
  {
    expressionStatement = false,
    arrowBody = false,
    exportDefault = false,
    forHead = false,
    forInHead = false,
    forOfHead = false,
  },
): boolean {
  let stackIndex = printStack.length - 1;
  let currentNode = printStack[stackIndex];
  stackIndex -= 1;
  let currentParent = printStack[stackIndex];

  const contextFieldByType: { [type: string]: string } = {
    ExpressionStatement: "expression",
    ExportDefaultDeclaration: "declaration",
    ArrowFunctionExpression: "body",
    ForStatement: "init",
    ForInStatement: "left",
    ForOfStatement: "left",
  };
  const contextEnabledByType: { [type: string]: boolean } = {
    ExpressionStatement: expressionStatement,
    ExportDefaultDeclaration: exportDefault,
    ArrowFunctionExpression: arrowBody,
    ForStatement: forHead,
    ForInStatement: forInHead,
    ForOfStatement: forOfHead,
  };
  const postfixFieldByType: { [type: string]: string | null } = {
    MemberExpression: "object",
    OptionalMemberExpression: "object",
    CallExpression: "callee",
    OptionalCallExpression: "callee",
    NewExpression: "callee",
    TaggedTemplateExpression: "tag",
    TSNonNullExpression: null,
  };

  while (stackIndex >= 0) {
    if (!isNode(currentParent)) {
      return false;
    }

    const parentType = currentParent.type;
    const parentRecord = currentParent as any;
    const contextEnabled = contextEnabledByType[parentType];
    const contextField = contextFieldByType[parentType];

    if (contextEnabled) {
      const expectedRelation: { [key: string]: t.Node } = {};
      expectedRelation[contextField] = currentNode;
      const expectedKeys = Object.keys(expectedRelation);
      let contextMatches = true;
      for (
        let keyIndex = 0;
        keyIndex < expectedKeys.length;
        keyIndex += 1
      ) {
        const expectedKey = expectedKeys[keyIndex];
        const actualChild = parentRecord[expectedKey];
        const expectedChild = expectedRelation[expectedKey];
        if (actualChild !== expectedChild) {
          contextMatches = false;
        }
      }
      if (contextMatches) {
        return true;
      }
    }

    let continueWalk = false;
    let hasPostfix = false;
    const isKnownPostfixParent = Object.prototype.hasOwnProperty.call(
      postfixFieldByType,
      parentType,
    );
    const postfixField = postfixFieldByType[parentType];

    if (isKnownPostfixParent) {
      if (postfixField == null) {
        hasPostfix = true;
      } else {
        const postfixChild = parentRecord[postfixField];
        hasPostfix = postfixChild === currentNode;
      }
    }

    if (hasPostfix) {
      continueWalk = parentType !== "NewExpression";
    }

    if (!continueWalk) {
      if (isSequenceExpression(currentParent)) {
        const expressions = parentRecord.expressions;
        continueWalk = expressions[0] === currentNode;
      } else if (isConditional(currentParent)) {
        continueWalk = parentRecord.test === currentNode;
      } else if (isBinary(currentParent)) {
        continueWalk = parentRecord.left === currentNode;
      } else if (isAssignmentExpression(currentParent)) {
        continueWalk = parentRecord.left === currentNode;
      }
    }

    if (continueWalk) {
      currentNode = currentParent;
      stackIndex -= 1;
      currentParent = printStack[stackIndex];
    } else {
      return false;
    }
  }

  return false;
}

